prompt --application/pages/page_00004
begin
wwv_flow_imp_page.create_page(
 p_id=>4
,p_name=>'Detalle Bar'
,p_alias=>'DETALLE-BAR'
,p_step_title=>'Detalle Bar'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'window.API_BASE = ''https://taller-3-base-de-datos-gdmd.onrender.com/bares'';',
'window.barId = parseInt(apex.item(''P4_BAR_ID'').getValue());',
'',
'function cargarComentarios() {',
'  fetch(`${window.API_BASE}/${window.barId}/comentarios`)',
'    .then(res => res.json())',
'    .then(data => {',
'      const container = document.getElementById(''comentarios-container'');',
'      if (!data || data.length === 0) {',
unistr('        container.innerHTML = ''<p style="color:#888;">No hay comentarios a\00FAn. \00A1S\00E9 el primero!</p>'';'),
'        return;',
'      }',
'      container.innerHTML = data.map(c => `',
'        <div style="border:1px solid #ddd; border-radius:8px; padding:12px; margin-bottom:10px; background:#fafafa;">',
unistr('          <strong>${c.autor || ''An\00F3nimo''}</strong>'),
'          <span style="color:#888; font-size:0.85em; margin-left:10px;">',
'            ${c.fecha ? new Date(c.fecha).toLocaleDateString(''es-CO'') : ''''}',
'          </span>',
'          <p style="margin-top:6px; margin-bottom:0;">${c.texto || c.comentario || ''''}</p>',
'        </div>',
'      `).join('''');',
'    })',
'    .catch(() => {',
'      document.getElementById(''comentarios-container'').innerHTML =',
'        ''<p style="color:red;">Error cargando comentarios.</p>'';',
'    });',
'}',
'',
'function cargarEventos() {',
'  fetch(`${window.API_BASE}/${window.barId}/eventos`)',
'    .then(res => res.json())',
'    .then(data => {',
'      const container = document.getElementById(''eventos-container'');',
'      if (!data || data.length === 0) {',
unistr('        container.innerHTML = ''<p style="color:#888;">No hay eventos registrados a\00FAn.</p>'';'),
'        return;',
'      }',
'      container.innerHTML = data.map(e => {',
'        const camposExtra = Object.entries(e)',
'          .filter(([k]) => ![''bar_id'',''nombre'',''fecha_creacion''].includes(k))',
'          .map(([k, v]) => `<span style="margin-right:12px;"><strong>${k}:</strong> ${v}</span>`)',
'          .join('''');',
'        return `',
'          <div style="border:1px solid #ddd; border-radius:8px; padding:12px; margin-bottom:10px; background:#f0f7ff;">',
unistr('            <strong style="font-size:1.1em;">\D83C\DF89 ${e.nombre}</strong>'),
'            <span style="color:#888; font-size:0.85em; margin-left:10px;">',
'              ${e.fecha_creacion ? new Date(e.fecha_creacion).toLocaleDateString(''es-CO'') : ''''}',
'            </span>',
'            <div style="margin-top:8px; color:#555;">${camposExtra}</div>',
'          </div>',
'        `;',
'      }).join('''');',
'    })',
'    .catch(() => {',
'      document.getElementById(''eventos-container'').innerHTML =',
'        ''<p style="color:red;">Error cargando eventos.</p>'';',
'    });',
'}',
'',
'cargarComentarios();',
'cargarEventos();'))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'03'
,p_last_updated_by=>'CO_B167_SQL_S05'
,p_last_upd_yyyymmddhh24miss=>'20260517014643'
);
