,p_event_id=>wwv_flow_imp.id(110268633820011462131)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'const texto = apex.item(''P_TEXTO_COMENTARIO'').getValue();',
'if (!texto.trim()) {',
unistr('  apex.message.showErrors([{ type: ''error'', location: ''page'', message: ''El comentario no puede estar vac\00EDo.'' }]);'),
'  return;',
'}',
'',
'fetch(`${window.API_BASE}/${window.barId}/comentarios`, {',
'  method: ''POST'',',
'  headers: { ''Content-Type'': ''application/json'' },',
'  body: JSON.stringify({',
'    bar_id: window.barId,',
'    texto: texto,',
'    autor: apex.env.APP_USER',
'  })',
'}).then(() => {',
'  apex.item(''P_TEXTO_COMENTARIO'').setValue('''');',
unistr('  apex.message.showPageSuccess(''\00A1Comentario enviado exitosamente!'');'),
'  setTimeout(() => location.reload(), 2000);',
'});'))
);
wwv_flow_imp_page.create_page_da_event(
 p_id=>wwv_flow_imp.id(110268634715599462140)
,p_name=>'Crear Evento'
,p_event_sequence=>20
,p_triggering_element_type=>'BUTTON'
,p_triggering_button_id=>wwv_flow_imp.id(110268634620799462139)
,p_bind_type=>'bind'
,p_execution_type=>'IMMEDIATE'
,p_bind_event_type=>'click'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(110268634880150462141)
,p_event_id=>wwv_flow_imp.id(110268634715599462140)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'const nombre = apex.item(''P_EVENTO_NOMBRE'').getValue();',
'if (!nombre.trim()) {',
'  apex.message.showErrors([{ type: ''error'', location: ''page'', message: ''El nombre del evento es obligatorio.'' }]);',
'  return;',
'}',
'',
'const evento = { nombre: nombre };',
'',
'const campo1 = apex.item(''P_EVENTO_CAMPO1_NOMBRE'').getValue();',
'const valor1 = apex.item(''P_EVENTO_CAMPO1_VALOR'').getValue();',
'if (campo1.trim() && valor1.trim()) {',
'  evento[campo1.trim()] = valor1.trim();',
'}',
'',
'const campo2 = apex.item(''P_EVENTO_CAMPO2_NOMBRE'').getValue();',
'const valor2 = apex.item(''P_EVENTO_CAMPO2_VALOR'').getValue();',
'if (campo2.trim() && valor2.trim()) {',
'  evento[campo2.trim()] = valor2.trim();',
'}',
'',
'fetch(`${window.API_BASE}/${window.barId}/eventos`, {',
'  method: ''POST'',',
'  headers: { ''Content-Type'': ''application/json'' },',
'  body: JSON.stringify(evento)',
'}).then(() => {',
'  apex.item(''P_EVENTO_NOMBRE'').setValue('''');',
'  apex.item(''P_EVENTO_CAMPO1_NOMBRE'').setValue('''');',
'  apex.item(''P_EVENTO_CAMPO1_VALOR'').setValue('''');',
'  apex.item(''P_EVENTO_CAMPO2_NOMBRE'').setValue('''');',
'  apex.item(''P_EVENTO_CAMPO2_VALOR'').setValue('''');',
unistr('  apex.message.showPageSuccess(''\00A1Evento creado exitosamente!'');'),
'  setTimeout(() => location.reload(), 800);',
'});'))
);
end;
